// SRV Farsi Creative V2 — local [TEST] lifecycle harness. ISOLATED: no production access.
//
// Runs the SRV Studio preview server (real public/ app, stub Supabase, local storage, DRY-RUN YouTube) behind a thin
// front proxy that answers SRV Farsi /api/generate with the REAL V2 handler (lib/srvFarsiCreativeV2.mjs). The model is
// not called: the handler's network is a stub that replays a package really generated by the V2 brain in the live
// [TEST] runs (run4.json) for the requested Artist/Mood, plus its recorded judge scores. Control endpoints:
//   /__cv2/flag?mode=on|test|off   server flag seen by the V2 handler (default on)
//   /__cv2/failfirst?n=1           make the next n generations break the locked structure (gate failure → retry)
//   /__cv2/calls                   what the V2 handler received
//
//   node tests/srv/srvf-creative-v2-live/lifecycle-harness.mjs [--port 4191] [--runs ~/MMM/srv-farsi-creative-v2/run4.json]
import http from 'node:http';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { startPreview } from '../studio-v2-preview/server.mjs';
import { srvfCv2Handle, _resetSrvfCv2FlagCache } from '../../../lib/srvFarsiCreativeV2.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '../../..');
const arg = (k, d) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : d; };
const PORT = Number(arg('--port', 4191));
const RUNS = arg('--runs', path.join(os.homedir(), 'MMM', 'srv-farsi-creative-v2', 'run4.json'));
const DATA = path.join(os.homedir(), 'MMM', 'srv-farsi-creative-v2', 'lifecycle-preview-state.json');

const runs = JSON.parse(fs.readFileSync(RUNS, 'utf8')).filter(r => r.package);
const inner = await startPreview({ publicDir: path.join(ROOT, 'public'), port: PORT + 1, dataFile: DATA, quiet: true });
const innerOrigin = `http://127.0.0.1:${PORT + 1}`;
let flag = 'on', failFirst = 0; const calls = [];

function recordedRaw(artist, mood) {
  const r = runs.find(x => x.artist === artist && x.mood === mood) || runs[0];
  const p = r.package;
  return { raw: { ...p, artist, mood, excludeStyles: p.excludeStyles }, judge: p.creativeGateResults && p.creativeGateResults.judge };
}
function stubFetch(body) {
  const { raw, judge } = recordedRaw(body.artist, body.mood);
  return async (url, opt = {}) => {
    const j = (o, s = 200) => ({ ok: s < 300, status: s, json: async () => o, text: async () => JSON.stringify(o) });
    if (String(url).includes('/app_settings')) return j([{ value: flag }]);
    if (String(url).includes('/generation_memory')) return j([]);
    if (String(url).includes('api.anthropic.com')) {
      const b = JSON.parse(opt.body);
      if (b.model.includes('haiku')) return j({ content: [{ type: 'text', text: JSON.stringify(judge) }] });
      let out = raw;
      if (failFirst > 0) { failFirst--; out = { ...raw, lyrics: raw.lyrics.replace(/\[VERSE 2([^\]]*)\]/, '[BRIDGE]\nیک خط اضافه\n\n[VERSE 2$1]') }; }
      return j({ content: [{ type: 'text', text: JSON.stringify(out) }] });
    }
    return j({}, 404);
  };
}
const readBody = req => new Promise(r => { const c = []; req.on('data', d => c.push(d)); req.on('end', () => r(Buffer.concat(c))); });

http.createServer(async (req, res) => {
  const u = new URL(req.url, `http://127.0.0.1:${PORT}`);
  if (u.pathname === '/__cv2/flag') { flag = u.searchParams.get('mode') || flag; _resetSrvfCv2FlagCache(); res.end(JSON.stringify({ flag })); return; }
  if (u.pathname === '/__cv2/failfirst') { failFirst = Number(u.searchParams.get('n') || 1); res.end(JSON.stringify({ failFirst })); return; }
  if (u.pathname === '/__cv2/calls') { res.setHeader('Content-Type', 'application/json'); res.end(JSON.stringify(calls, null, 1)); return; }
  // Simulated Silk Road Voices connection with playlist permission (the inner preview only models SRV Studio).
  if (u.pathname === '/api/ops' && u.searchParams.get('action') === 'srv_farsi_playlists') {
    calls.push({ at: new Date().toISOString(), playlists: req.method });
    res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ ok: true, canAddToPlaylists: true, added: [], playlists: [] })); return;
  }
  const buf = req.method === 'GET' || req.method === 'HEAD' ? null : await readBody(req);
  if (u.pathname === '/api/generate' && buf) {
    let body = null; try { body = JSON.parse(buf.toString('utf8')); } catch (_) {}
    if (body && body.engine === 'SRV Farsi' && body.srvFarsiCreativeV2 === true) {
      _resetSrvfCv2FlagCache();
      const out = await srvfCv2Handle(body, { fetchImpl: stubFetch(body), apiKey: 'stub', supabaseUrl: 'http://stub', supabaseKey: 'stub' });
      calls.push({ at: new Date().toISOString(), body: { ...body, feedback: body.feedback }, flag, code: out.json.code || 'success', failed: (out.json.failed || []).map(f => f.gate) });
      res.writeHead(out.status, { 'Content-Type': 'application/json' }); res.end(JSON.stringify(out.json)); return;
    }
  }
  const p = http.request(innerOrigin + req.url, { method: req.method, headers: { ...req.headers } }, pr => {
    const h = { ...pr.headers };
    if (h.location) h.location = String(h.location).replace(innerOrigin, `http://127.0.0.1:${PORT}`);
    res.writeHead(pr.statusCode, h); pr.pipe(res);
  });
  p.on('error', e => { res.writeHead(502); res.end(String(e)); });
  if (buf) p.end(buf); else p.end();
}).listen(PORT, '127.0.0.1', () => console.log(`SRV Farsi Creative V2 lifecycle harness: http://127.0.0.1:${PORT}  (inner preview ${innerOrigin}; ${inner && inner.origin ? 'ok' : ''})`));
